insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-10-06','verbeterd','Medewerkers','Werkmaatschappij kiezen bij een nieuwe medewerker',
   'Bij het aanmaken van een medewerker kies je nu meteen de werkmaatschappij, zodat je die niet achteraf op de kaart hoeft in te vullen. In Bouw7 stel je de werkmaatschappij nog zelf in. Lukt het aanmaken in Bouw7 niet, dan zie je daar nu ook een melding van.');
